// One folder per run so concurrent submissions never collide.
const runId = ($json.submittedAt || String(Date.now())).replace(/[^a-zA-Z0-9]/g, '');
const dir = `/tmp/burncaptions-${runId}`;

const binKeys = Object.keys($input.item.binary || {});
if (binKeys.length === 0) {
  throw new Error('No video was uploaded - the Video File field came through empty.');
}
const binaryKey = binKeys[0];
const upload = $input.item.binary[binaryKey];
const originalName = upload.fileName || 'video';
const extMatch = originalName.match(/\.([a-zA-Z0-9]+)$/);
const ext = extMatch ? extMatch[1] : 'mp4';

const text = ($json['Caption Text'] || '').trim();
if (!text) throw new Error('Caption Text is empty - nothing to caption.');
const words = text.split(/\s+/).filter(Boolean);
if (words.length === 0) throw new Error('Caption Text has no words after splitting.');

// Caption Style label -> ASS style parameters (BGR hex, ASS alignment codes: 2=bottom-center, 8=top-center)
const styleLabel = $json['Caption Style'] || 'Classic (white text, black outline, bottom)';
const STYLE_PRESETS = {
  classic: { primary: '&H00FFFFFF', secondary: '&H0000FFFF', outline: '&H+1234567890', back: '&H+1234567890', outlineWidth: 3, alignment: 2, fontSizeFactor: 0.033, marginVFactor: 0.06 },
  bold: { primary: '&H00FFFFFF', secondary: '&H0000A5FF', outline: '&H+1234567890', back: '&H+1234567890', outlineWidth: 5, alignment: 2, fontSizeFactor: 0.042, marginVFactor: 0.06 },
  top: { primary: '&H00FFFFFF', secondary: '&H0000FFFF', outline: '&H+1234567890', back: '&H+1234567890', outlineWidth: 3, alignment: 8, fontSizeFactor: 0.033, marginVFactor: 0.06 },
};
let stylePreset = STYLE_PRESETS.classic;
let styleKey = 'classic';
if (styleLabel.startsWith('Bold')) { stylePreset = STYLE_PRESETS.bold; styleKey = 'bold'; }
else if (styleLabel.startsWith('Top')) { stylePreset = STYLE_PRESETS.top; styleKey = 'top'; }
else if (styleLabel.startsWith('Plain')) { stylePreset = STYLE_PRESETS.classic; styleKey = 'plain'; }

return {
  json: {
    ...$json,
    dir,
    binaryKey,
    videoPath: `${dir}/input.${ext}`,
    assPath: `${dir}/captions.ass`,
    outputPath: `${dir}/captioned.mp4`,
    words,
    styleKey,
    stylePreset,
  },
  binary: $input.item.binary,
};

// Create the temp folder (Execute Command) wipes json + binary - re-attach both
// from Prepare Run so the uploaded video survives to the write-to-disk step.
const run = $('Prepare Run').item.json;
return { json: run, binary: $('Prepare Run').item.binary };

// FFprobe (Execute Command) replaces the item with stdout/stderr/exitCode -
// stdout has "width=...", "height=...", "duration=..." on separate lines.
const probe = $json;
const run = $('Prepare Run').item.json;

if (probe.exitCode !== undefined && probe.exitCode !== 0) {
  throw new Error('Could not read the video: ' + (probe.stderr || '').slice(-400));
}
const stdout = probe.stdout || '';
const num = (key, fallback) => {
  const m = stdout.match(new RegExp(`${key}=(\\S+)`));
  const v = m ? parseFloat(m[1]) : NaN;
  return isFinite(v) && v > 0 ? v : fallback;
};
const duration = num('duration', 0);
if (!duration) throw new Error(`ffprobe returned no usable duration. Raw output: ${stdout}`);
const width = Math.round(num('width', 1080));
const height = Math.round(num('height', 1920));

// No real per-word timing signal for arbitrary narration - distribute words
// across the full video duration weighted by character length. Estimated, not
// word-perfect (documented in Additional info for buyers).
const words = run.words;
const charLens = words.map(w => w.length);
const totalChars = charLens.reduce((a, b) => a + b, 0) || words.length;
let cursor = 0;
const timedWords = words.map((w, i) => {
  const dur = (charLens[i] / totalChars) * duration;
  const start = cursor;
  const end = Math.min(duration, cursor + dur);
  cursor = end;
  return { word: w, start, end };
});

// Group words into lines by a max-character budget so lines stay readable.
const MAX_LINE_CHARS = 32;
const lines = [];
let current = [];
let currentLen = 0;
for (const tw of timedWords) {
  if (currentLen + tw.word.length + 1 > MAX_LINE_CHARS && current.length) {
    lines.push(current);
    current = [];
    currentLen = 0;
  }
  current.push(tw);
  currentLen += tw.word.length + 1;
}
if (current.length) lines.push(current);

const fmtTime = (t) => {
  const h = Math.floor(t / 3600);
  const m = Math.floor((t % 3600) / 60);
  const s = t % 60;
  return `${h}:${String(m).padStart(2, '0')}:${s.toFixed(2).padStart(5, '0')}`;
};

const sp = run.stylePreset;
const fontSize = Math.round(height * sp.fontSizeFactor);
const assHeader = `[Script Info]
ScriptType: v4.00+
PlayResX: ${width}
PlayResY: ${height}
[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Karaoke,Arial,${fontSize},${sp.primary},${sp.secondary},${sp.outline},${sp.back},-1,0,0,0,100,100,0,0,1,${sp.outlineWidth},2,${sp.alignment},60,60,${Math.round(height*sp.marginVFactor)},1
[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
`;

// Plain mode skips per-word \\k timing entirely and burns one static line of
// text per group, fading in/out at the line's start/end - a real subtitle-style
// burn, not a karaoke-highlight with the colors turned off.
const usesKaraoke = run.styleKey !== 'plain';
let events = '';
for (const line of lines) {
  const lineStart = line[0].start;
  const lineEnd = line[line.length - 1].end;
  let text = '';
  if (usesKaraoke) {
    for (const tw of line) {
      const durCs = Math.max(1, Math.round((tw.end - tw.start) * 100));
      text += `{\\k${durCs}}${tw.word} `;
    }
  } else {
    text = line.map(tw => tw.word).join(' ');
  }
  events += `Dialogue: 0,${fmtTime(lineStart)},${fmtTime(lineEnd)},Karaoke,,0,0,0,,${text.trim()}\n`;
}

const assContent = assHeader + events;

return {
  json: { ...run, duration, width, height, lineCount: lines.length, wordCount: words.length, captionStyle: run.styleKey, karaoke: usesKaraoke },
  binary: { assFile: { data: Buffer.from(assContent).toString('base64'), mimeType: 'text/plain', fileName: 'captions.ass' } },
};

const cmdResult = $json;
const run = $('Build the karaoke captions (.ass)').item.json;
if (cmdResult.exitCode !== undefined && cmdResult.exitCode !== 0) {
  throw new Error('FFmpeg failed to burn captions: ' + (cmdResult.stderr || '').slice(-800));
}
return {
  json: {
    outputPath: run.outputPath,
    wordCount: run.wordCount,
    lineCount: run.lineCount,
    durationSeconds: run.duration,
    captionStyle: run.captionStyle,
  },
};

// Read/Write File's read operation replaces json with file metadata only -
// merge the caption report back in so the output has both the numbers and the file.
const report = $('Verify the burn succeeded').item.json;
return { json: { ...report, file: $json }, binary: $input.item.binary };
